var raw = $json.content && $json.content[0] && $json.content[0].text || JSON.stringify($json);
var parsed;
try {
  var s = raw.indexOf('{');
  var e = raw.lastIndexOf('}');
  parsed = JSON.parse(raw.slice(s, e+1));
} catch(err) {
  return { json: { xato: true, tur: 'PARSE_FAIL', xabar: String(err) } };
}
var inp = $("Mavzu bo'yicha filtrlash").first().json;
return { json: {
  burchaklar: parsed.burchaklar || {},
  sarlavha: parsed.sarlavha || '',
  faktlar: inp.faktlar,
  mavzu_kod: inp.mavzu_kod,
  avatar_kod: inp.avatar_kod,
  foydalanuvchi_matni: inp.foydalanuvchi_matni,
  ok: !parsed.xato
} };

Burchaklar tekshiruvi.kod:
var b = $json.burchaklar || {};
var xatolar = [];
if (!b.yt_long || b.yt_long.length !== 1) xatolar.push("yt_long: 1 ta bolishi kerak, topildi: " + (b.yt_long ? b.yt_long.length : 0));
if (!b.yt_short || b.yt_short.length !== 3) xatolar.push("yt_short: 3 ta bolishi kerak, topildi: " + (b.yt_short ? b.yt_short.length : 0));
if (!b.tiktok || b.tiktok.length !== 4) xatolar.push("tiktok: 4 ta bolishi kerak, topildi: " + (b.tiktok ? b.tiktok.length : 0));
if (!b.reel || b.reel.length !== 2) xatolar.push("reel: 2 ta bolishi kerak, topildi: " + (b.reel ? b.reel.length : 0));
if (!b.carousel || b.carousel.length !== 1) xatolar.push("carousel: 1 ta bolishi kerak, topildi: " + (b.carousel ? b.carousel.length : 0));
if (!b.tg_post || b.tg_post.length !== 1) xatolar.push("tg_post: 1 ta bolishi kerak, topildi: " + (b.tg_post ? b.tg_post.length : 0));
if (!b.thumbnail || b.thumbnail.length !== 1) xatolar.push("thumbnail: 1 ta bolishi kerak, topildi: " + (b.thumbnail ? b.thumbnail.length : 0));
var faktlar = $json.faktlar || [];
var faktRaqamlar = [];
for (var i = 0; i < faktlar.length; i++) {
  var qv = String(faktlar[i].qiymat || faktlar[i].matn_tr || "");
  var m = qv.match(new RegExp("[0-9]+","g")) || [];
  for (var j = 0; j < m.length; j++) faktRaqamlar.push(m[j]);
}
var allBurchakText = JSON.stringify(b);
var pctM = allBurchakText.match(new RegExp("%([0-9]+)","g")) || [];
for (var pi = 0; pi < pctM.length; pi++) {
  var num = pctM[pi].replace("%","");
  var found = false;
  for (var fk = 0; fk < faktRaqamlar.length; fk++) { if (faktRaqamlar[fk].indexOf(num) >= 0) { found = true; break; } }
  if (!found) xatolar.push("Ixtiro raqam: " + pctM[pi] + " faktlarda yoq");
}
// Build job_id
var now = new Date();
var sana = now.toISOString().slice(0,10).replace(new RegExp('-','g'),'');
var rand = Math.random().toString(36).slice(2,6).toUpperCase();
var job_id = $json.mavzu_kod + '-' + sana + '-' + rand;

return { json: {
  job_id: job_id,
  mavzu_kod: $json.mavzu_kod,
  avatar_kod: $json.avatar_kod,
  til: 'tr',
  test_rejim: false,
  sarlavha: $json.sarlavha,
  faktlar: $json.faktlar,
  burchaklar: $json.burchaklar,
  tekshiruv_xatolar: xatolar,
  holat: xatolar.length === 0 ? 'PASS' : 'FAIL',
  provenance: { workflow: 'zb-00-mavzu-paketi', model: 'claude-sonnet-4-6', urinish: 1, vaqt: now.toISOString() }
} };
